#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20};
    auto it = s.begin();

    // *it = 15;  // ERROR: Dereferenced value is const, cannot modify key

    // Correct way to 'modify' a set element:
    if (it != s.end()) {
        int old_val = *it;
        it = s.erase(it); // Erase returns iterator to next element
        s.insert(old_val + 5); 
    }

    // Output: 15, 20
    for (int x : s) std::cout << x << " ";
    std::cout << "\n";
}
